    return FfiConverterTypeSealedMessage.lower(value)
}


public 
enum SeamError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The peer was never paired (its identity key wasn't pinned).
     */
    case NotPaired
    /**
     * The peer's key doesn't match the one from pairing: treat as an attack, don't retry.
     */
    case UntrustedIdentity
    /**
     * Anything else: malformed, tampered or replayed input.
     */
    case Invalid(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension SeamError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSeamError: FfiConverterRustBuffer {
    typealias SwiftType = SeamError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SeamError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotPaired
        case 2: return .UntrustedIdentity
        case 3: return .Invalid(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SeamError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotPaired:
            writeInt(&buf, Int32(1))
        
        
        case .UntrustedIdentity:
            writeInt(&buf, Int32(2))
        
        
        case let .Invalid(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSeamError_lift(_ buf: RustBuffer) throws -> SeamError {
    return try FfiConverterTypeSeamError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSeamError_lower(_ value: SeamError) -> RustBuffer {
    return FfiConverterTypeSeamError.lower(value)
}
